// ── Vocabulary Lock ─────────────────────────────────────────────────────────────
// Post-generation deterministic word replacement per genre.
// Replaces genre-inappropriate words that slipped through the LLM with
// genre-appropriate synonyms from the whitelist/replacement map.
// enforceVocabularyLock accepts either a single genreKey (string) or an array of keys.
// When an array is provided, it uses the merged module from mergeGenreModules().
// subject parameter (optional): the user's song subject — words appearing in the subject
// are PROTECTED and will not be replaced. This prevents the vocabulary lock from destroying
// subject-relevant words (e.g., "sun" in a song about "the last hour of daylight").
function enforceVocabularyLock(lyrics, genreKeyOrKeys, subject, wantsPatois) {
  const genreKeys = Array.isArray(genreKeyOrKeys) ? genreKeyOrKeys : (genreKeyOrKeys ? [genreKeyOrKeys] : []);
  const mod = genreKeys.length > 1 ? mergeGenreModules(genreKeys) : (genreKeys.length === 1 ? GENRE_VOCABULARY_MODULES[genreKeys[0]] : null);
  if (!mod || !mod.replacements) return lyrics;
  // When the user did NOT select a (Patois) genre variant, skip English→Patois vocabulary replacements.
  // The reggae module's replacements are entirely English-to-Patois conversions ("i"→"mi", "the"→"di", etc.)
  // that should only apply when the user explicitly wants Patois lyrics.
  if (wantsPatois === false && genreKeys.some(k => ["reggae", "dubstep_patois"].includes(k))) {
    return lyrics;
  }
  // Build a set of protected words from the subject (lowercase, split on non-alpha)
  const protectedWords = new Set();
  if (subject) {
    const words = subject.toLowerCase().replace(/[^a-z\s]/g, "").split(/\s+/).filter(Boolean);
    for (const w of words) {
      if (w.length > 2) protectedWords.add(w); // only protect words > 2 chars (skip "a", "of", "in")
    }
  }
  let result = lyrics;
  for (const [bad, good] of Object.entries(mod.replacements)) {
    // Skip replacement if the bad word is protected by the subject
    if (protectedWords.has(bad.toLowerCase())) continue;
    // Case-insensitive replacement preserving section labels
    const re = new RegExp(`(?<!\\[)\\b${bad.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b(?![^\\]]*\\])`, "gi");
    result = result.replace(re, (match) => {
      // Preserve capitalization of original
      if (match[0] === match[0].toUpperCase() && good[0]) {
        return good[0].toUpperCase() + good.slice(1);
      }
      return good;
    });
  }
  return result;
}

