// replaceSlopWords accepts either a single genreKey (string) or an array of keys.
// When an array is provided, it merges slop replacements from all genres in priority order.
function replaceSlopWords(lyrics, genreKeyOrKeys) {
  const genreKeys = Array.isArray(genreKeyOrKeys) ? genreKeyOrKeys : (genreKeyOrKeys ? [genreKeyOrKeys] : []);
  const replacements = genreKeys.length > 1
    ? buildMergedSlopReplacements(genreKeys)
    : { ...GENRE_SLOP_REPLACEMENTS._default, ...(GENRE_SLOP_REPLACEMENTS[genreKeys[0]] || {}) };
  let result = lyrics;
  for (const [bad, good] of Object.entries(replacements)) {
    const re = new RegExp(`(?<!\\[)\\b${bad.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b(?![^\\]]*\\])`, "gi");
    result = result.replace(re, (match) => {
      if (match[0] === match[0].toUpperCase() && good[0]) {
        return good[0].toUpperCase() + good.slice(1);
      }
      return good;
    });
  }
  return result;
}

// ── processLyricsWithGenre — Master Orchestrator ────────────────────────────────
// Chains: fixSectionLabels → enforceLineCounts → enforceVocabularyLock → replaceSlopWords
// Called from the /llm endpoint after LLM generates lyrics, before returning to the client.
// processLyricsWithGenre accepts either a single genreKey (string) or an array of keys.
// When an array is provided, it merges vocabulary and slop replacements from all genres.
// subject parameter (optional): the user's song subject — words appearing in the subject
// are PROTECTED from vocabulary replacements to preserve subject relevance.
function processLyricsWithGenre(lyrics, genreKeyOrKeys, languageFallback, subject, wantsPatois) {
  const genreKeys = Array.isArray(genreKeyOrKeys) ? genreKeyOrKeys : (genreKeyOrKeys ? [genreKeyOrKeys] : []);
  let result = lyrics;
  // Step 0: Strip parenthetical instructions (CRITICAL — ACE-Step sings anything in parentheses)
  const beforeParen = result;
  result = stripParentheticalInstructions(result);
  if (beforeParen !== result) console.log(`[ParenStrip] Removed parenthetical instructions from lyrics`);
  // Step 1: Fix section labels (existing)
  result = fixSectionLabels(result);
  // Step 2: Enforce line counts (genre-aware — allows flexible verse lengths for metal, hiphop, etc.)
  result = enforceLineCounts(result, genreKeys);
  // Step 2b: Ensure [Outro] exists and has lyrics (safety net for LLM dropping the outro)
  {
    const lines = result.split("\n");
    const lastNonEmptyIdx = lines.length - 1 - [...lines].reverse().findIndex(l => l.trim());
    const lastNonEmpty = lines[lastNonEmptyIdx]?.trim() || "";
    // UPDATED: Detect any tag starting with [Outro, allowing for descriptions like [Outro: Fade]
    const hasOutroSection = /^\[Outro(\s*[:\-].*)?\]$/i.test(lastNonEmpty);
    const allOutroSections = lines.filter(l => /^\[Outro/i.test(l.trim()));
    // Check if the last [Outro] section has any lyric lines after it
    let outroHasLyrics = false;
    if (hasOutroSection) {
      const outroIdx = lastNonEmptyIdx;
      // Find the ACTUAL start of the last outro section to count its lyrics
      let startOfLastOutro = 0;
      for(let i = lines.length - 1; i >= 0; i--) {
        if (/^\[Outro/i.test(lines[i].trim())) {
          startOfLastOutro = i;
          break;
        }
      }
      const linesAfterOutro = lines.slice(startOfLastOutro + 1).filter(l => l.trim() && !/^\[.+\]$/.test(l.trim()));
      outroHasLyrics = linesAfterOutro.length >= 2;
    }
    if (!hasOutroSection || !outroHasLyrics) {
      // Extract the last chorus or verse lines to use as outro fodder
      const chorusLines = [];
      let inChorus = false;
      for (let i = lines.length - 1; i >= 0; i--) {
        const l = lines[i].trim();
        if (/^\[Chorus\]/i.test(l)) { inChorus = true; continue; }
        if (inChorus && /^\[.+\]$/.test(l)) break; // hit another section header
        if (inChorus && l) chorusLines.unshift(l);
        if (chorusLines.length >= 6) break;
      }
      // If no chorus found, try last verse
      let outroLines = chorusLines.length >= 2
        ? chorusLines.slice(-4) // last 3-4 lines of the final chorus — a proper wind-down
        : [];
      // If chorus didn't have enough lines, supplement from the last verse
      if (outroLines.length < 3) {
        const verseLines = [];
        let inVerse = false;
        for (let i = lines.length - 1; i >= 0; i--) {
          const l = lines[i].trim();
          if (/^\[Verse/i.test(l)) { inVerse = true; continue; }
          if (inVerse && /^\[.+\]$/.test(l)) break;
          if (inVerse && l) verseLines.unshift(l);
          if (verseLines.length >= 4) break;
        }
        // Combine: use remaining chorus lines + verse lines to reach 3-4 total
        const needed = 4 - outroLines.length;
        const extra = verseLines.slice(-needed);
        if (extra.length > 0) outroLines = [...outroLines, ...extra];
      }
      if (outroLines.length >= 2) {
        // Remove any existing empty [Outro] section
        const cleanedLines = [];
        let skipEmptyOutro = false;
        for (let i = 0; i < lines.length; i++) {
          const l = lines[i].trim();
          if (/^\[Outro\]$/i.test(l)) {
            // Check if next non-empty line is another section header or end of file
            let nextLyricIdx = i + 1;
            while (nextLyricIdx < lines.length && !lines[nextLyricIdx].trim()) nextLyricIdx++;
            const nextLine = lines[nextLyricIdx]?.trim() || "";
            if (!nextLine || /^\[.+\]$/.test(nextLine)) {
              skipEmptyOutro = true;
              continue; // skip the empty outro header
            }
          }
          if (skipEmptyOutro && /^\[.+\]$/.test(l) && !/^\[Outro\]/i.test(l)) {
            skipEmptyOutro = false;
          }
          if (!skipEmptyOutro) cleanedLines.push(lines[i]);
        }
        // Append [Outro] with the last chorus lines as a fade
        const outroSection = ["", "[Outro]", ...outroLines, ""];
        result = cleanedLines.join("\n").replace(/\n{3,}/g, "\n\n") + "\n" + outroSection.join("\n");
        console.log(`[OutroFix] Auto-inserted [Outro] with ${outroLines.length} lines (echoed from final chorus/verse)`);
      } else {
        // No chorus lines available — add a minimal [Outro] header (instrumental fade)
        result = result.replace(/\s*$/, "") + "\n\n[Outro]\n\n";
        console.log(`[OutroFix] Added empty [Outro] section (no chorus lines available for echo)`);
      }
    }
  }
  // Step 3: Apply language fallback if the user selected an unsupported language
  if (languageFallback && languageFallback.fallback) {
    // Append a note to the lyrics metadata (the caller can use this)
    console.log(`[LangFallback] ${languageFallback.name} — ${languageFallback.note}`);
  }
  // Step 4: Vocabulary Lock — replace genre-inappropriate words
  // Supports multi-genre: passes the full array so merged module is used
  if (genreKeys.length > 0) {
    const hasVocab = genreKeys.some(k => GENRE_VOCABULARY_MODULES[k]);
    if (hasVocab) {
      const before = result;
      result = enforceVocabularyLock(result, genreKeys, subject, wantsPatois);
      const changes = before !== result;
      const label = genreKeys.length > 1 ? `multi-genre [${genreKeys.join("+")}]` : genreKeys[0];
      if (changes) console.log(`[VocabLock] Applied genre vocabulary lock for ${label}`);
    }
  }
  // Step 5: Slop Replacer — deterministic slop word replacement
  // Supports multi-genre: passes the full array so merged slop dict is used
  if (genreKeys.length > 0) {
    const before = result;
    result = replaceSlopWords(result, genreKeys);
    const changes = before !== result;
    const label = genreKeys.length > 1 ? `multi-genre [${genreKeys.join("+")}]` : genreKeys[0];
    if (changes) console.log(`[SlopReplacer] Applied genre-specific slop replacement for ${label}`);
  }
  // Step 6: Syllable Density Enforcement — restructure lines that exceed genre syllable limits
  // Reads maxSyllables from the merged genre module's lineRules.
  // Attempts to trim dense lines by removing filler words, then splitting at natural boundaries.
  if (genreKeys.length > 0) {
    const merged = genreKeys.length > 1 ? mergeGenreModules(genreKeys) : (genreKeys.length === 1 ? GENRE_VOCABULARY_MODULES[genreKeys[0]] : null);
    const maxSyl = merged?.lineRules?.maxSyllables;
    if (typeof maxSyl === 'number' && maxSyl > 0) {
      const lines = result.split('\n');
      const restructured = [];
      let denseFixed = 0;
      let denseSkipped = 0;
      let worstLine = '';
      let worstCount = 0;

      // Filler words safe to remove (articles, auxiliary verbs, weak prepositions)
      const FILLER_WORDS = new Set(['a', 'an', 'the', 'is', 'are', 'was', 'were', 'been', 'being',
        'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'shall', 'should',
        'may', 'might', 'can', 'could', 'must', 'that', 'which', 'who', 'whom',
        'very', 'really', 'just', 'also', 'even', 'still', 'already', 'always']);

      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed || /^\[.+\]$/.test(trimmed)) { restructured.push(line); continue; }

        const words = trimmed.match(/[a-zA-Z']+/g);
        if (!words) { restructured.push(line); continue; }
        const sylCount = words.reduce((acc, w) => acc + countSyllables(w), 0);

        if (sylCount <= maxSyl) {
          restructured.push(line);
          continue;
        }

        // Attempt 1: Remove filler words to reduce syllable count
        const allWords = trimmed.split(/(\s+)/); // preserve whitespace
        const withoutFillers = allWords.filter(w => {
          const clean = w.replace(/[^a-zA-Z']/g, '').toLowerCase();
          return !FILLER_WORDS.has(clean) || w.length <= 1;
        });
        const trimmedResult = withoutFillers.join('').replace(/ {2,}/g, ' ').trim();
        const trimmedWords = trimmedResult.match(/[a-zA-Z']+/g) || [];
        const trimmedSyl = trimmedWords.reduce((acc, w) => acc + countSyllables(w), 0);

        if (trimmedSyl <= maxSyl && trimmedResult.length > 10) {
          // Filler removal worked
          restructured.push(line.replace(trimmed, trimmedResult));
          denseFixed++;
          console.log(`[SyllableDensity] Trimmed ${sylCount}→${trimmedSyl} syl: "${trimmed.slice(0, 40)}..." → "${trimmedResult.slice(0, 40)}..."`);
          continue;
        }

        // Attempt 2: Split at natural phrase boundary (comma, dash, " and ", " but ", " or ")
        const splitPoints = [];
        const commaMatches = [...trimmed.matchAll(/,\s*/g)];
        for (const m of commaMatches) splitPoints.push({ pos: m.index, type: ',' });
        const andMatches = [...trimmed.matchAll(/\s+and\s+/gi)];
        for (const m of andMatches) splitPoints.push({ pos: m.index + 1, type: ' and ' });
        const butMatches = [...trimmed.matchAll(/\s+but\s+/gi)];
        for (const m of butMatches) splitPoints.push({ pos: m.index + 1, type: ' but ' });
        const dashMatches = [...trimmed.matchAll(/\s*[—–-]\s*/g)];
        for (const m of dashMatches) splitPoints.push({ pos: m.index, type: ' - ' });

        if (splitPoints.length > 0) {
          // Pick the split point closest to the middle
          const mid = trimmed.length / 2;
          splitPoints.sort((a, b) => Math.abs(a.pos - mid) - Math.abs(b.pos - mid));
          const best = splitPoints[0];
          const part1 = trimmed.slice(0, best.pos).trim();
          const part2 = trimmed.slice(best.pos + best.type.length).trim();
          const p1Words = (part1.match(/[a-zA-Z']+/g) || []);
          const p2Words = (part2.match(/[a-zA-Z']+/g) || []);
          const p1Syl = p1Words.reduce((a, w) => a + countSyllables(w), 0);
          const p2Syl = p2Words.reduce((a, w) => a + countSyllables(w), 0);

          if (p1Syl <= maxSyl && p2Syl <= maxSyl && part1.length > 5 && part2.length > 5) {
            restructured.push(part1);
            restructured.push(part2);
            denseFixed++;
            console.log(`[SyllableDensity] Split ${sylCount} syl (${p1Syl}+${p2Syl}): "${trimmed.slice(0, 40)}..."`);
            continue;
          }
        }

        // Could not restructure — keep original and log warning
        restructured.push(line);
        denseSkipped++;
        if (sylCount > worstCount) { worstCount = sylCount; worstLine = trimmed.slice(0, 60); }
      }

      result = restructured.join('\n');
      if (denseFixed > 0 || denseSkipped > 0) {
        const label = genreKeys.length > 1 ? `multi-genre [${genreKeys.join("+")}]` : genreKeys[0];
        const parts = [];
        if (denseFixed > 0) parts.push(`${denseFixed} trimmed/split`);
        if (denseSkipped > 0) parts.push(`${denseSkipped} over-limit (untrimmable, worst: ${worstCount} syl)`);
        console.log(`[SyllableDensity] ${label} (${maxSyl} syl limit): ${parts.join(', ')}`);
      }
    }
  }
  return result;
}

// ── resolveLanguageFallback ─────────────────────────────────────────────────────
// Takes a vocalLanguage code and returns { fallback, name, note } if unsupported,
// or null if the language is natively supported by the engine.
function resolveLanguageFallback(langCode) {
  if (!langCode) return null;
  const entry = LANGUAGE_FALLBACK_MAP[langCode];
  return entry || null;
}

// ── resolveGenreFromStyles ──────────────────────────────────────────────────────
// Maps user-selected genre strings to GENRE_VOCABULARY_MODULES keys.
// Returns { primary, all } where:
//   primary = the highest-priority matched genre key (or null)
//   all     = array of ALL matched genre keys in user-selection priority order
// Priority is determined by the order genres appear in the user's selection list
// (first selected = highest priority), NOT by hardcoded iteration order.
function resolveGenreFromStyles(genres) {
  if (!genres || !genres.length) return { primary: null, all: [] };
  const genreMap = {
    "metal": ["metal", "heavy metal", "death metal", "black metal", "thrash metal", "doom metal", "progressive metal", "power metal", "symphonic metal", "groove metal"],
    "reggae": ["reggae", "dub", "ska", "rocksteady", "dancehall", "lovers rock", "roots reggae", "ragga"],
    "kpop": ["k-pop", "kpop", "korean pop", "j-pop", "jpop", "c-pop", "cpop", "mandopop", "cantopop", "korean r&b"],
    "hiphop": ["hip-hop", "hiphop", "rap", "trap", "drill", "grime", "boom bap", "conscious hip-hop", "gangsta rap", "mumble rap", "lo-fi hip-hop", "r&b"],
    "blues": ["blues", "delta blues", "chicago blues", "texas blues", "blues rock", "piano blues", "acoustic blues", "electric blues"],
    "punk": ["punk", "punk rock", "pop punk", "post-punk", "hardcore punk", "ska punk", "anarcho-punk", "garage punk"],
    "folk": ["folk", "indie folk", "folk rock", "celtic folk", "traditional folk", "singer-songwriter", "americana", "country folk", "bluegrass"],
    // REMOVED: "acapella" — acapella, beatbox, barbershop quartet, vocal percussion, ASMR
    // These genres are purely vocal or use techniques ACE-Step was not trained on.
    // The model cannot generate realistic music for these styles.
    "duet": ["duet", "duets", "male female duet", "male and female vocals", "dual vocals", "alternating vocals"],
    "porn": ["porn sfw", "sfw porn", "porn instrumentation", "sfw adult pop"],
    "porngroove": ["porn", "porn groove", "70s porn groove", "sensual lounge", "erotic funk", "sexy bedroom soul", "slow jam", "bedroom r&b", "sleazy funk", "nsfw porn", "adult lyrics"],
    "dj": ["dj", "turntablism", "turntablist", "turntable", "scratch", "scratching", "turntables", "deejay", "turntable battle", "scratch battle"],
    "dualdj": ["dual dj", "dual turntablist", "dj battle", "dj duel", "turntable duel", "dj crew", "dj collab", "dj tag team", "scratch battle crew", "dual scratching"],
    "klezmer": ["klezmer", "eastern european jewish", "jewish folk", "clarinet folk", "wedding band eastern european", "romani folk"],
    "mariachi": ["mariachi", "mexican folk", "mexican traditional", "ranchera", "son jalisciense", "corrido", "huapango", "mexican band"],
    "bhangra": ["bhangra", "punjabi folk", "punjab folk", "indian folk dance", "punjabi music", "giddha"],
    "andean": ["andean", "andean folk", "quechua music", "charango music", "quena music", "andes music", "inca music", "south american folk", "latin folk andean"],
    "dubstep": ["dubstep", "brostep", "riddim dubstep", "tearout", "uk dubstep", "deep dubstep", "melodic dubstep", "english dubstep"],
    "dubstep_patois": ["dubstep (patois)", "patois dubstep", "jamaican dubstep", "dancehall dubstep", "ragga dubstep", "dubstep patois", "raggamuffin dubstep"]
  };
  const genresLower = genres.map(g => g.toLowerCase().trim());
  const matched = [];
  const matchedSet = new Set();
  // Iterate USER-selected genres first (preserves selection order as priority),
  // then check each against all genreMap modules. First module match per user
  // genre wins. This ensures the user's selection order determines priority.
  for (const genre of genresLower) {
    for (const [key, aliases] of Object.entries(genreMap)) {
      if (matchedSet.has(key)) continue; // already matched — skip duplicate
      for (const alias of aliases) {
        if (genre.includes(alias) || alias.includes(genre)) {
          matched.push(key);
          matchedSet.add(key);
          break; // this module matched — move to next user genre
        }
      }
    }
  }
  return { primary: matched[0] || null, all: matched };
}

