// ── clampBpmForGenre ───────────────────────────────────────────────────────────
// Clamps the LLM-generated BPM to a realistic range for the given genre(s).
// Accepts both resolved genreKeys (module keys like "metal") AND the original
// user-selected genre strings (like "doom metal") for subgenre-specific lookup.
// If BPM is null/undefined/0, returns null (caller should use genre default).
// Returns { bpm, clamped, original } — clamped is true if the value was changed.
function clampBpmForGenre(bpm, genreKeys, originalGenres) {
  if (!bpm || bpm <= 0) return { bpm: null, clamped: false, original: bpm };
  const gKeys = genreKeys ? (Array.isArray(genreKeys) ? genreKeys : [genreKeys]) : [];
  const oGenres = originalGenres ? (Array.isArray(originalGenres) ? originalGenres : [originalGenres]) : [];
  // Build combined lookup list: original genre strings FIRST (more specific),
  // then resolved module keys (more generic). This ensures "doom metal" is
  // checked before "metal", giving the narrower subgenre range priority.
  const lookupKeys = [];
  for (const g of oGenres) {
    const gLower = g.toLowerCase().trim();
    if (gLower && !lookupKeys.includes(gLower)) lookupKeys.push(gLower);
  }
  for (const k of gKeys) {
    if (k && !lookupKeys.includes(k)) lookupKeys.push(k);
  }
  // Find the narrowest applicable range from the combined lookup list
  let bestRange = null;
  let bestSpecificity = -1;
  for (const key of lookupKeys) {
    const range = GENRE_BPM_RANGES[key];
    if (range) {
      // More specific genres (e.g., "death metal" = 12 chars) override generic (e.g., "metal" = 5 chars)
      const specificity = key.length;
      if (specificity > bestSpecificity || !bestRange) {
        bestRange = range;
        bestSpecificity = specificity;
      }
    }
  }
  // If no genre-specific range found, use a very wide default
  if (!bestRange) bestRange = [30, 300];
  const [min, max] = bestRange;
  const original = bpm;
  let clamped = false;
  let result = bpm;
  if (bpm < min) { result = min; clamped = true; }
  else if (bpm > max) { result = max; clamped = true; }
  if (clamped) {
    console.log(`[BPM] Clamped ${original} BPM to ${result} (genre range: ${min}-${max})`);
  }
  return { bpm: result, clamped, original };
}

// ── mergeGenreModules ──────────────────────────────────────────────────────────
// Merges multiple GENRE_VOCABULARY_MODULES into a single blended module.
// Priority order: primary genre (first) gets heaviest influence.
// Rules:
//   - Whitelist: union of all (primary words come first)
//   - Blacklist: union of all (if ANY genre bans a word, it's banned)
//   - Replacements: layered in priority order (later genres can override)
//   - LineRules: primary wins for conflicting rules; secondary additive booleans merge
function mergeGenreModules(genreKeys) {
  if (!genreKeys || !genreKeys.length) return null;
  const merged = { whitelist: [], blacklist: [], replacements: {}, lineRules: {} };
  const seenWhitelist = new Set();
  const seenBlacklist = new Set();
  for (let i = 0; i < genreKeys.length; i++) {
    const mod = GENRE_VOCABULARY_MODULES[genreKeys[i]];
    if (!mod) continue;
    // Whitelist: union (add unique words, primary first)
    if (mod.whitelist) {
      for (const w of mod.whitelist) {
        if (!seenWhitelist.has(w)) { merged.whitelist.push(w); seenWhitelist.add(w); }
      }
    }
    // Blacklist: union (if ANY genre bans it, it's banned)
    if (mod.blacklist) {
      for (const b of mod.blacklist) {
        if (!seenBlacklist.has(b)) { merged.blacklist.push(b); seenBlacklist.add(b); }
      }
    }
    // Replacements: primary genre's replacements take priority.
    // Secondary genres can ADD new replacements but cannot override primary's.
    if (mod.replacements) {
      if (i === 0) {
        // Primary genre: all replacements apply
        Object.assign(merged.replacements, mod.replacements);
      } else {
        // Secondary genres: only add NEW keys, don't override primary's
        for (const [k, v] of Object.entries(mod.replacements)) {
          if (!(k in merged.replacements)) merged.replacements[k] = v;
        }
      }
    }
    // LineRules: primary gets all rules; secondary genres only contribute additive rules
    if (mod.lineRules) {
      if (i === 0) {
        Object.assign(merged.lineRules, mod.lineRules);
      } else {
        // Additive boolean rules — secondary genres can enable features but not disable primary's
        if (mod.lineRules.allowPatois) merged.lineRules.allowPatois = true;
        if (mod.lineRules.allowRomanizedKorean) merged.lineRules.allowRomanizedKorean = true;
        if (mod.lineRules.allowSlantRhyme) merged.lineRules.allowSlantRhyme = true;
        if (mod.lineRules.preferAABRhyme) merged.lineRules.preferAABRhyme = true;
        if (mod.lineRules.preferShortLines) merged.lineRules.preferShortLines = true;
        if (mod.lineRules.preferMetered) merged.lineRules.preferMetered = true;
        if (mod.lineRules.preferCaps) merged.lineRules.preferCaps = true;
        if (mod.lineRules.allowAdLibs) merged.lineRules.allowAdLibs = true;
        if (mod.lineRules.allowCallResponse) merged.lineRules.allowCallResponse = true;
        if (mod.lineRules.allowCallAndResponse) merged.lineRules.allowCallAndResponse = true;
        if (mod.lineRules.allowShouting) merged.lineRules.allowShouting = true;
        if (mod.lineRules.allowScratchEffects) merged.lineRules.allowScratchEffects = true;
        if (mod.lineRules.allowDuetVocals) merged.lineRules.allowDuetVocals = true;
        if (mod.lineRules.allowRefrain) merged.lineRules.allowRefrain = true;
        if (mod.lineRules.allowSlang) merged.lineRules.allowSlang = true;
        if (mod.lineRules.preferPatois) merged.lineRules.preferPatois = true;
        if (mod.lineRules.preferBilingual) merged.lineRules.preferBilingual = true;
        // Numeric rules: use the STRICTEST (lowest) value across all genres
        if (typeof mod.lineRules.maxSyllables === 'number') {
          if (typeof merged.lineRules.maxSyllables !== 'number' || mod.lineRules.maxSyllables < merged.lineRules.maxSyllables) {
            merged.lineRules.maxSyllables = mod.lineRules.maxSyllables;
          }
        }
      }
    }
  }
  return merged;
}

// ── buildMergedSlopReplacements ────────────────────────────────────────────────
// Merges _default slop replacements with all matched genre-specific slop
// Merges slop replacements from multiple genres. Primary genre (first) takes priority.
// Secondary genres can ADD new slop words but cannot override primary's replacements.
function buildMergedSlopReplacements(genreKeys) {
  const merged = { ...GENRE_SLOP_REPLACEMENTS._default };
  for (let i = 0; i < genreKeys.length; i++) {
    const key = genreKeys[i];
    if (GENRE_SLOP_REPLACEMENTS[key]) {
      if (i === 0) {
        // Primary genre: all slop replacements apply
        Object.assign(merged, GENRE_SLOP_REPLACEMENTS[key]);
      } else {
        // Secondary genres: only add NEW keys, don't override primary's
        for (const [k, v] of Object.entries(GENRE_SLOP_REPLACEMENTS[key])) {
          if (!(k in merged)) merged[k] = v;
        }
      }
    }
  }
  return merged;
}

