    for (let vi = 0; vi < verseSections.length; vi++) {
      const sec = sections.filter(s => s.label === "V")[vi];
      if (!sec) continue;
      const allCapsLines = sec.lines.filter(l => l === l.toUpperCase() && l.replace(/[^a-zA-Z]/g, "").length > 2).length;
      const capsRatio = allCapsLines / sec.lines.length;
      const avgSyl = sec.lines.reduce((a, l) => a + syllablesInLine(l), 0) / sec.lines.length;
      // Intensity = caps ratio + syllable density
      intensities.push(capsRatio * 3 + (avgSyl / 15)); // normalize
    }
