        if (p.unresolved.length) {
          console.warn(`[AdapterSections] ${header} directive: unknown adapter key(s) ${p.unresolved.map((k) => `"${k}"`).join(", ")} \u2014 loaded triggers: ${triggers.join(", ")}`);
        }
