// server/src/services/lireek/llm/types.ts
var skipThinkingSignal = false;
function setSkipThinking() {
  skipThinkingSignal = true;
  console.log("[LLM] Skip-thinking signal received");
}
function resetSkipThinking() {
  skipThinkingSignal = false;
}

// server/src/services/lireek/llm/base.ts
var LLMProvider = class {
  availableModels = [];
  toInfo() {
    return {
      id: this.id,
      name: this.name,
      available: this.isAvailable(),
      models: this.availableModels.length ? this.availableModels : this.defaultModel ? [this.defaultModel] : [],
      default_model: this.defaultModel
    };
  }
};
function noThinkSystemPrompt(systemPrompt) {
  return `${systemPrompt}

/no_think`;
}
async function readSSE(response, onChunk, extractText, extractDisplayOnly) {
  if (!response.body) return "";
  const reader = response.body.getReader();
  const decoder = new TextDecoder("utf-8");
  let fullText = "";
  let buffer = "";
  const emit = onChunk || (() => {}); /* no-op when caller doesn't need chunks */
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const lines2 = buffer.split("\n");
      buffer = lines2.pop() || "";
      for (const line of lines2) {
        if (line.startsWith("data: ")) {
          const dataStr = line.slice(6).trim();
          if (dataStr === "[DONE]") {
            reader.cancel();
            return fullText;
          }
          try {
            const parsed = JSON.parse(dataStr);
            if (parsed.choices?.[0]?.finish_reason) {
              const lastText = extractText(parsed);
              if (lastText) {
                fullText += lastText;
                emit(lastText);
              }
              continue;
            }
            if (extractDisplayOnly) {
              const displayText = extractDisplayOnly(parsed);
              if (displayText) {
                emit(displayText);
                if (skipThinkingSignal) {
                  const thinkCheck = fullText + displayText;
                  if (thinkCheck.includes("<think>") && !thinkCheck.includes("</think>")) {
                    reader.cancel();
                    return fullText;
                  }
                }
                continue;
              }
            }
            const text3 = extractText(parsed);
            if (text3) {
              fullText += text3;
              emit(text3);
              if (skipThinkingSignal && fullText.includes("<think>") && !fullText.includes("</think>")) {
                reader.cancel();
                return fullText;
              }
            }
          } catch (e) {
          }
        }
      }
    }
  } finally {
    reader.releaseLock();
  }
  return fullText;
}

// server/src/services/lireek/llm/gemini.ts
init_config();
var GeminiProvider = class _GeminiProvider extends LLMProvider {
  id = "gemini";
  name = "Google Gemini";
  get defaultModel() {
    return config.lireek.geminiModel;
  }
  availableModels = ["gemini-2.5-flash"];
  // initial fallback, replaced by API fetch
  /** Cache fetched models so we don't hit the API on every listProviders() call */
  _cachedModels = null;
  _cacheExpiry = 0;
  static CACHE_TTL = 5 * 60 * 1e3;
  // 5 minutes
  isAvailable() {
    return !!config.lireek.geminiApiKey;
  }
  /** Fetch available models from the Gemini API, filtered to those that support generateContent */
  async getRemoteModels() {
    const now = Date.now();
    if (this._cachedModels && now < this._cacheExpiry) return this._cachedModels;
    if (!config.lireek.geminiApiKey) return this.availableModels;
    try {
      const allModels = [];
      let pageToken;
      do {
        const url = new URL("https://generativelanguage.googleapis.com/v1beta/models");
        url.searchParams.set("key", config.lireek.geminiApiKey);
        url.searchParams.set("pageSize", "100");
        if (pageToken) url.searchParams.set("pageToken", pageToken);
        const resp = await fetch(url.toString(), { signal: AbortSignal.timeout(8e3) });
        if (!resp.ok) {
          console.warn(`[Gemini] models.list failed: ${resp.status}`);
          break;
        }
        const data2 = await resp.json();
        if (Array.isArray(data2.models)) allModels.push(...data2.models);
        pageToken = data2.nextPageToken;
      } while (pageToken);
      if (allModels.length === 0) return this.availableModels;
      const generative = allModels.filter((m) => m.supportedGenerationMethods?.includes("generateContent")).map((m) => m.name.replace(/^models\//, "")).filter((name) => !name.includes("embedding") && !name.includes("aqa") && !name.includes("tunedModels"));
      if (generative.length === 0) return this.availableModels;
      generative.sort((a, b) => {
        const verA = parseFloat(a.match(/(\d+\.\d+)/)?.[1] || "0");
        const verB = parseFloat(b.match(/(\d+\.\d+)/)?.[1] || "0");
        if (verB !== verA) return verB - verA;
        const isFlashA = a.includes("flash") ? 0 : 1;
        const isFlashB = b.includes("flash") ? 0 : 1;
        if (isFlashA !== isFlashB) return isFlashA - isFlashB;
        return a.length - b.length;
      });
      this._cachedModels = generative;
      this._cacheExpiry = now + _GeminiProvider.CACHE_TTL;
      this.availableModels = generative;
      return generative;
    } catch (err) {
      console.warn(`[Gemini] Failed to fetch models: ${err.message}`);
      return this.availableModels;
    }
  }
  async toInfoAsync() {
    const models = await this.getRemoteModels();
    return {
      ...this.toInfo(),
      models: models.length ? models : [this.defaultModel],
      default_model: this.defaultModel
    };
  }
  async call(systemPrompt, userPrompt, model, onChunk) {
    const modelName = model || this.defaultModel;
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:${onChunk ? "streamGenerateContent?alt=sse&" : "generateContent?"}key=${config.lireek.geminiApiKey}`;
    const payload = {
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents: [{ role: "user", parts: [{ text: userPrompt }] }]
    };
    const resp = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(3e5)
    });
    if (!resp.ok) throw new Error(`Gemini API error: ${resp.status} ${await resp.text()}`);
    if (onChunk) {
      return await readSSE(resp, onChunk, (data2) => data2.candidates?.[0]?.content?.parts?.[0]?.text || null);
    } else {
      const data2 = await resp.json();
      return data2.candidates?.[0]?.content?.parts?.[0]?.text || "";
    }
  }
};

// server/src/services/lireek/llm/openai.ts
init_config();
var OpenAIProvider = class extends LLMProvider {
  id = "openai";
  name = "OpenAI / ChatGPT";
  get defaultModel() {
    return config.lireek.openaiModel;
  }
  availableModels = ["gpt-4o", "gpt-4o-mini", "gpt-4-turbo", "gpt-3.5-turbo"];
  isAvailable() {
    return !!config.lireek.openaiApiKey;
  }
  async call(systemPrompt, userPrompt, model, onChunk) {
    const url = "https://api.openai.com/v1/chat/completions";
    const payload = {
      model: model || this.defaultModel,
      messages: [{ role: "system", content: systemPrompt }, { role: "user", content: userPrompt }],
      stream: !!onChunk
    };
    const resp = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${config.lireek.openaiApiKey}`
      },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(3e5)
    });
    if (!resp.ok) throw new Error(`OpenAI error: ${resp.status} ${await resp.text()}`);
    if (onChunk) {
      return await readSSE(resp, onChunk, (data2) => data2.choices?.[0]?.delta?.content || null, (data2) => data2.choices?.[0]?.delta?.reasoning_content || null);
    } else {
      const data2 = await resp.json();
      return data2.choices?.[0]?.message?.content || "";
    }
  }
};

// server/src/services/lireek/llm/anthropic.ts
init_config();
var AnthropicProvider = class extends LLMProvider {
  id = "anthropic";
  name = "Anthropic / Claude";
  get defaultModel() {
    return config.lireek.anthropicModel;
  }
  availableModels = ["claude-3-5-sonnet-20241022", "claude-3-5-haiku-20241022", "claude-3-opus-20240229"];
  isAvailable() {
    return !!config.lireek.anthropicApiKey;
  }
  async call(systemPrompt, userPrompt, model, onChunk) {
    const url = "https://api.anthropic.com/v1/messages";
    const payload = {
      model: model || this.defaultModel,
      max_tokens: 4096,
      system: systemPrompt,
      messages: [{ role: "user", content: userPrompt }],
      stream: !!onChunk
    };
    const resp = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": config.lireek.anthropicApiKey,
        "anthropic-version": "2023-06-01"
      },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(3e5)
    });
    if (!resp.ok) throw new Error(`Anthropic error: ${resp.status} ${await resp.text()}`);
    if (onChunk) {
      let fullText = "";
      await readSSE(resp, (text3) => {
        fullText += text3;
        onChunk(text3);
      }, (data2) => {
        if (data2.type === "content_block_delta" && data2.delta?.text) return data2.delta.text;
        return null;
      });
      return fullText;
    } else {
      const data2 = await resp.json();
      return data2.content?.[0]?.text || "";
    }
  }
};

