init_config();
var OllamaProvider = class extends LLMProvider {
  id = "ollama";
  name = "Ollama (Local)";
  _cachedModels = null;
  _cacheTime = 0;
  get defaultModel() {
    return config.lireek.ollamaModel;
  }
  isAvailable() {
    return true;
  }
  async getLocalModels() {
    try {
      const resp = await fetch(`${config.lireek.ollamaBaseUrl}/api/tags`, { signal: AbortSignal.timeout(1e4) });
      if (!resp.ok) return this._cachedModels || [];
      const data2 = await resp.json();
      this.availableModels = data2.models?.map((m) => m.name) || [];
      if (this.availableModels.length > 0) {
        this._cachedModels = this.availableModels;
        this._cacheTime = Date.now();
      }
      return this.availableModels;
    } catch {
      return this._cachedModels || [];
    }
  }
  async toInfoAsync() {
    // Use cached models if fetched within last 5 minutes
    const cached = this._cachedModels && (Date.now() - this._cacheTime < 5 * 60 * 1000);
    const models = cached ? this._cachedModels : await this.getLocalModels();
    return {
      ...this.toInfo(),
      models: models.length ? models : this.defaultModel ? [this.defaultModel] : [],
      default_model: models.length ? models[0] : this.defaultModel
    };
  }
  async call(systemPrompt, userPrompt, model, onChunk, options) {
    const url = `${config.lireek.ollamaBaseUrl}/api/chat`;
    const noThink = !!options?.noThink;
    const payload = {
      model: model || this.defaultModel,
      messages: [
        { role: "system", content: noThink ? noThinkSystemPrompt(systemPrompt) : systemPrompt },
        { role: "user", content: userPrompt }
      ],
      stream: true,
      options: {
        num_predict: 8196,
        // Always set sampling options — temperature/presence_penalty control output variety
        // even when thinking is enabled (applied to non-thinking output tokens)
        temperature: options?.temperature ?? 0.7,
        top_p: options?.top_p ?? 0.8,
        top_k: 20,
        presence_penalty: options?.presence_penalty ?? 1.5
      }
    };
    if (noThink) {
      payload.think = false;
    }
    const doFetch = () => fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(9e5)
    });
    let resp = await doFetch();
    if (!resp.ok && noThink && resp.status === 400 && "think" in payload) {
      delete payload.think;
      resp = await doFetch();
    }
    if (!resp.ok) throw new Error(`Ollama error: ${resp.status} ${await resp.text()}`);
    /* Always use streaming reader — even when onChunk is null.
       This keeps the connection alive during long cold-starts and token generation,
       preventing AbortSignal.timeout from firing while Ollama is still processing. */
    if (resp.body) {
      const reader = resp.body.getReader();
      const decoder = new TextDecoder();
      let fullText = "";
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          const chunkLines = decoder.decode(value, { stream: true }).split("\n");
          for (const line of chunkLines) {
            if (!line.trim()) continue;
            try {
              const parsed = JSON.parse(line);
              const reasoning = parsed.message?.reasoning_content;
              if (reasoning) {
                if (onChunk) onChunk(reasoning);
                continue;
              }
              const content = parsed.message?.content;
              if (content) {
                fullText += content;
                if (onChunk) onChunk(content);
                if (skipThinkingSignal && fullText.includes("<think>") && !fullText.includes("</think>")) {
                  reader.cancel();
                  return fullText;
                }
              }
            } catch (e) {
            }
          }
        }
      } finally {
        reader.releaseLock();
      }
      return fullText;
    } else {
      /* Fallback: no body (shouldn't happen with stream:true, but handle gracefully) */
      const data2 = await resp.json();
      return data2.message?.content || "";
    }
  }
};

