function buildRefinementPrompt(originalLyrics, artistName, title, profile, originalSlop) {
  const lines2 = [`Artist: ${artistName}`, `Original Title: ${title}`, ""];
  if (profile) {
    lines2.push("=== INTENDED LANE PROFILE (match this style) ===");
    lines2.push(`Themes: ${(profile.themes || []).slice(0, 8).join(", ")}`);
    if (profile.tone_and_mood) lines2.push(`Tone & mood: ${profile.tone_and_mood}`);
    if (profile.vocabulary_notes) lines2.push(`Vocabulary: ${profile.vocabulary_notes}`);
    if (profile.imagery_patterns) lines2.push(`Imagery patterns: ${profile.imagery_patterns}`);
    if (profile.signature_devices) lines2.push(`Signature devices: ${profile.signature_devices}`);
    if (profile.narrative_techniques) lines2.push(`Narrative techniques: ${profile.narrative_techniques}`);
    if (profile.emotional_arc) lines2.push(`Emotional arc: ${profile.emotional_arc}`);
    if (profile.structural_patterns) lines2.push(`Structure: ${profile.structural_patterns}`);
    if (profile.perspective) lines2.push(`Perspective / voice: ${profile.perspective}`);
    if (profile.rhyme_schemes?.length) lines2.push(`Rhyme schemes: ${profile.rhyme_schemes.join(", ")}`);
    if (profile.rhyme_quality) {
      const rq = profile.rhyme_quality;
      const total = Object.values(rq).reduce((a, b) => a + b, 0);
      if (total > 0) lines2.push(`Rhyme mix: ${Math.round(100 * (rq.perfect || 0) / total)}% perfect, ${Math.round(100 * (rq.slant || 0) / total)}% slant, ${Math.round(100 * (rq.assonance || 0) / total)}% assonance`);
    }
    const ms = profile.meter_stats;
    if (ms) lines2.push(`Line density: ~${ms.avg_syllables_per_line ?? "?"} syl/line (\u03C3=${ms.syllable_std_dev ?? "?"}), ~${ms.avg_words_per_line ?? "?"} words/line`);
    const rs = profile.repetition_stats;
    if (rs) {
      lines2.push(`Hook behavior: ${rs.pattern || "unknown"} (${rs.chorus_repetition_pct ?? 0}% chorus repetition)`);
      if ((rs.chorus_repetition_pct ?? 0) >= 20) lines2.push("Calibration: This artist uses heavy chorus repetition \u2014 ensure hook lines repeat.");
      else if ((rs.chorus_repetition_pct ?? 0) < 15) lines2.push("Calibration: This artist uses light repetition \u2014 be subtle with hooks.");
    }
    if (profile.avg_verse_lines || profile.avg_chorus_lines) lines2.push(`Verse/chorus: avg ${profile.avg_verse_lines} verse lines, avg ${profile.avg_chorus_lines} chorus lines`);
    if (profile.song_subjects && typeof profile.song_subjects === "object") {
      const titles = Object.keys(profile.song_subjects);
      if (titles.length) {
        lines2.push("", "=== ORIGINAL SONG TITLES (check for plagiarism) ===");
        for (const t of titles) lines2.push(`  \u2022 ${t}`);
      }
    }
    lines2.push("");
  }
  if (originalSlop?.length) {
    lines2.push("=== KNOWN ISSUES TO FIX ===");
    lines2.push("The original lyrics contain the following AI-clich\xE9s or circular phrases that MUST be replaced:");
    lines2.push(`Words/Phrases to Remove: ${originalSlop.join(", ")}`);
    lines2.push("");
  }
  lines2.push("=== ORIGINAL LYRICS ===", "", originalLyrics, "", "=== INSTRUCTIONS ===", "");
  lines2.push("Refine the lyrics above according to the refinement rules.");
  lines2.push("Keep as much of the original as possible \u2014 only change what genuinely needs fixing.");
  lines2.push(`Maintain ${artistName}'s distinctive style throughout.`);
  lines2.push("Now output the refined version (Title line first, then lyrics with [Section] headers):");
  return lines2.join("\n");
}
async function refineLyricsStreaming(originalLyrics, artistName, title, providerName, model, profile, onChunk) {
  const provider = getProvider(providerName);
  const effectiveModel = model || provider.defaultModel;
  const slopScan = scanForSlop(originalLyrics);
  const foundSlop = [...slopScan.layers.blacklisted_words.found, ...slopScan.layers.blacklisted_phrases.found];
  const userPrompt = buildRefinementPrompt(originalLyrics, artistName, title, profile, foundSlop);
  let raw = await provider.call(cacheBustPrompt(REFINEMENT_SYSTEM_PROMPT), userPrompt, effectiveModel, onChunk);
  raw = stripThinkingBlocks(raw);
  raw = raw.replace(/<\|[a-z_]+\|>/g, "");
  raw = raw.replace(/\s*\((?:Hook|You|Repeat|x\d|Refrain|Spoken|Whispered|Ad[- ]?lib|Echo)\)\s*/gi, "");
  raw = raw.replace(/ +$/gm, "");
  let refinedTitle = title;
  const rLines = raw.trim().split("\n");
  for (let i = 0; i < rLines.length; i++) {
    const match = rLines[i].match(/^(?:Title:\s*|#\s*)(.*)/i);
    if (match) {
      refinedTitle = match[1].trim().replace(/^['"]|['"]$/g, "");
      const rest = rLines.slice(i + 1);
      while (rest.length && !rest[0].trim()) rest.shift();
      raw = rest.join("\n");
      break;
    }
  }
  raw = postprocessLyrics(raw);
  raw = fixSectionLabels(raw);
  raw = fixAPrefix(raw);
  raw = enforceLineCounts(raw);
  const slopResult = scanForSlop(raw);
  if (slopResult.ai_score > 0) {
    console.warn(
      `Refinement slop scan: score=${slopResult.ai_score} severity=${slopResult.severity}`,
      "words:",
      slopResult.layers.blacklisted_words.found,
      "phrases:",
      slopResult.layers.blacklisted_phrases.found,
      "overuse:",
      slopResult.layers.overuse.found.map((o) => `${o.word}(${o.count}x)`).join(", ") || "none",
      "hook_formulas:",
      slopResult.layers.hook_formulas.found.join(", ") || "none"
    );
  }
  return {
    lyrics: raw,
    provider: providerName,
    model: effectiveModel,
    title: refinedTitle,
    subject: "",
    bpm: 0,
    key: "",
    caption: "",
    duration: 0,
    system_prompt: REFINEMENT_SYSTEM_PROMPT,
    user_prompt: userPrompt
  };
}

