      console.log(`[Inspire/LLM] Generated ${raw.split("\n").length} lines of lyrics${extractedTitle ? `, title: "${extractedTitle}"` : ""}`);
      // ── Quality Analysis (pure read-only, does not modify lyrics) ────────────
      let qualityReport = null;
